      ...arr(ir.verification).flatMap((v) => v.verifies ? [["verification", v.id, v.verifies, "verifies"]] : []),
      ...arr(ir.decisions).flatMap((d) => d.supersededBy ? [["decision", d.supersededBy, d.id, "supersedes"]] : [])
